import pandas as pd

df = pd.read_csv('medicaid_managed_care_enrollment_2024.csv')
df_2024 = df[(df['Year'] == 2024) & (~df['State'].str.contains('TOTAL', case=False, na=False))].copy()

def parse_num(x):
    if pd.isna(x) or str(x).strip() in ['--', '', '-']:
        return 0
    return int(str(x).replace(',', '').strip())

df_2024['comp_mc'] = df_2024['Medicaid Enrollment in Comprehensive Managed Care'].apply(parse_num)
top3 = df_2024.sort_values(by='comp_mc', ascending=False).head(3)
result = top3['State'].tolist()

